; /** The track a soundcheck's offline conversion stopped on, and the converter's own reason. */ export type VscConvertFailedParams = { readonly file: string; readonly cause: string }; /** A discovery protocol that could not scan a specific link. */ export type BlindLinkParams = { readonly protocol: string; readonly scope: string }; /** A discovery protocol that could not scan at all (no link scope). */ export type BlindGlobalParams = { readonly protocol: string }; /** A probe that failed with a host/system error, named for the operator. */ export type ProbeErrorParams = { readonly error: string }; /** A link too busy to active-probe, with what the listen window actually saw. */ export type BusyLinkParams = { readonly rxDelta: number }; /** A reac-pw publishing a discovery state this build has no meaning for. */ export type UnknownProbeStateParams = { readonly state: string }; /** A reac-pw whose published sightings have all aged out. */ export type StaleProbeParams = { readonly seconds: number }; /** The NIC scopes reac-pw IS watching, for a NIC it is not. */ export type OtherScopesParams = { readonly scopes: string }; /** A device absent from a restored show, with its dependency clauses already joined. */ export type MissingHardwareParams = { readonly name: string; readonly clauses: string }; /** A count of restored patches/routes that depend on an absent device. */ export type DependentCountParams = { readonly n: number }; /** The NIC an absent box is configured on. */ export type ConfiguredIfaceParams = { readonly iface: string }; /** A stored value that disagrees with what the hardware reports. Both halves are parameters because the sentence around them is the locale's; `observed` is the one that wins. / export type ContradictionParams = { readonly declared: string; readonly observed: string }; /** The same, for a fact counted rather than named (a width, a channel count). */ export type ContradictionCountParams = { readonly declared: number; readonly observed: number }; /** A hardware-backed entity whose device is not on the rig: what it is, and which one. */ export type AbsentDeviceParams = { readonly kind: string; readonly id: string }; /** The device observed owning the clock pace alongside openmixer. */ export type ClockOwnerParams = { readonly owner: string }; /** The node driving the PipeWire graph. */ export type ClockDriverParams = { readonly label: string }; /** How fast xruns are landing right now (issue #657) — a RATE, never the running total. */ export type XrunRateParams = { readonly rate: number }; /** A device natively running a rate set the graph's own rate is not a member of — the follower-rate cross-check (2026-09-14). */ export type FollowerRateMismatchParams = { readonly device: string; readonly graphRate: number; readonly rates: string; readonly nearest: number; readonly ratio: number; }; /** A stage-order finding (2026-09-15-channel-stage-order.md §5) — which strip, and which two stages the desk is remarking on. The stage NAMES cross the wire, not their positions: a locale renders \"the gate runs after the compressor\", and an index would make every sentence a puzzle. / export type StageOrderParams = { readonly channel: string; readonly stage: string; readonly other: string; }; /** A bus's physical output route HEALED (2026-09-15-main-route-healing-and-output-exclusivity.md §3) — which bus, where it was, where it went, and which clause of the order chose. The PORT PAIRS cross the wire, not a device label: the operator has to be able to check the desk against what they see in a graph tool, and a friendly name cannot be looked up there. / export type RouteHealedParams = { readonly bus: string; readonly from: string; readonly to: string; readonly step: string; }; /** A bus whose destination died and for which NOTHING eligible exists — the console says so rather than routing into a port that is not there (§3). */ export type RouteNoTargetParams = { readonly bus: string }; /** A link the session manager made onto a physical output the console routes, and which the console removed (§5). The APP is what the operator recognises; the port is what they can check. */ export type ForeignLinkParams = { readonly app: string; readonly port: string }; /** An app stream the console PARKED rather than patching (§6, safe mode) — informational, so a browser that makes no sound has a visible reason. */ export type AppStreamParams = { readonly app: string }; /** A hand-made link the console ADOPTED into a bus's route row (§4) — the operator's own act, now desk state, so the next restart re-lays it instead of going silent again. */ export type RouteAdoptedParams = { readonly bus: string; readonly to: string }; /** A bus put BACK on the destination its row held before a heal, now that the card is on the graph again (§9g R2) — a heal is a tenancy and `healedFrom` is what remembers the lease. */ export type RouteRestoredParams = { readonly bus: string; readonly to: string }; /** The console cannot HOLD `default.audio.sink` at its parking sink (§6) — what it wanted and what the session manager is answering, so \"a new app is audible\" has a visible cause. */ export type DefaultSinkForeignParams = { readonly want: string; readonly got: string }; /** Safe mode's parking door THREW inside the heal cycle (§9k) — which call, so a dead metadata round-trip and a sink that could not be built are different sentences. */ export type ParkingDoorFailedParams = { readonly step: string }; /** A hold wrote the parking sink over a configured default that is not the console's (§9k) — the sink the operator's default named, so the override is never silent. */ export type DefaultSinkDisplacedParams = { readonly displaced: string }; /** A box's width came from the closed model table because no live device answered for it (`2026-08-22-stagebox-identity-and-device-model.md`, wire-over-table amendment).",paramType:`StageboxModelTableUsedParams`,params:[{name:`box`,type:`string`},{name:`model`,type:`string`}]}]},{label:`output routes: healing, exclusivity, safe mode (2026-09-15)`,codes:[{code:`output.route-healed.title`,doc:`A bus's destination stopped existing and the console re-routed it. Never silent: a heal is an act the console took on the operator's desk.`,paramType:`RouteHealedParams`,params:[{name:`bus`,type:`string`},{name:`from`,type:`string`},{name:`to`,type:`string`},{name:`step`,type:`string`}]},{code:`output.route-healed.detail`,doc:"The code → message bridge: THE registry of every operator-facing message core and the server may put on the wire, each mapped to the exact named fields its localised sentence interpolates. The rule (i18n design of record, §\"server/core send CODES\"): nothing below the UI ever emits display prose. A refusal, a warning, an undo label — each travels as a stable kebab/dotted CODE plus a small record of structured parameters, and the client renders it in the operator's own locale. Untranslatable payloads (a device id, a NIC name, a plugin product name, a count) ride as PARAMETERS; they are never baked into a sentence server-side, because a baked sentence cannot be translated and a re-ordered one cannot be un-baked. ## Why a registry and not just `string` A bare `{ code: string; params: Record<string, unknown> }` moves the failure to runtime: the sentence renders with `{scope}` still in it because the emitter sent `nic`. {@link MessageParams} pins each code to its parameter shape, so ```ts codedMessage('rt.budget', { pct: 92 }); // ok codedMessage('rt.budget', { percent: 92 }); // build error — wrong field codedMessage('rt.budget', {}); // build error — missing field codedMessage('not-a-real-code', {}); // build error — unknown code ``` and {@link AnyCodedMessage} is the discriminated union over every entry, so a consumer that switches on `code` gets that code's parameters typed with no assertion at the branch. ## Adding a message 1. Add the code + its parameter type to {@link MessageParams}. 2. Add it to {@link MESSAGE_CODES} (the build fails until you do — see `_NoUnlistedCode`). 3. Add the sentence to EVERY locale catalog (`web-ui/i18n/locales/<code>/messages.json`); the catalog-parity test fails until you do. / import type { InsertLatencyCode, LatencyBudgetParams } from './insert-latency-budget.js'; import type { StageboxAssignRefusal, StageboxAssignRefusalParams } from './stagebox.js'; import { LISTED_MESSAGE_CODES } from './message-codes-listed.js'; /** What a localised sentence may interpolate: wire-serialisable scalars only. */ export type MessageParamValue = string | number; /** The parameter record shape every {@link MessageParams} entry conforms to. */ export type MessageParamRecord = Readonly<Record<string, MessageParamValue>>; /** The parameter type of a code whose sentence interpolates nothing. */ export type NoMessageParams = Readonly<Record<string, never>>; // --------------------------------------------------------------------------- // Parameter shapes // // Declared as TYPE ALIASES, never interfaces: an anonymous/aliased object type carries an // implicit index signature, so it is assignable to `MessageParamRecord` at the translator // boundary. An `interface` would not be, and every call site would need a cast. // --------------------------------------------------------------------------- /** How much of the real-time budget the engine is spending. */ export type RtBudgetParams = { readonly pct: number }; /** How busy the engine was when a plugin analysis was refused. */ export type MeasurementBusyParams = { readonly pct: number }; /** Why the plugin host has no instance slot left: how many ids mod-host has (`max`, its own declared `0 ~ N` range) and how many of them are LEAKED — bypassed, un-racked, and still holding their id because mod-host's `remove` command segfaults this build, so an un-rack never returns a slot. Both numbers, because \"the plugin host is full\" leaves an operator guessing while \"9991 slots, 9991 of them leaked\" says the fix is to restart the host. / 